export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.89, 0.57, 0.57);

  const MASK_3D = 0x10000000;
  const MASK_GUI = 0x20000000;

  const mainCamera = new BABYLON.ArcRotateCamera(
    "cam",
    BABYLON.Tools.ToRadians(134.2),
    BABYLON.Tools.ToRadians(76.8),
    13,
    new BABYLON.Vector3(0, 1.6, 0),
    scene,
  );
  mainCamera.inertia = 0.4;
  mainCamera.wheelDeltaPercentage = 0.3;
  mainCamera.panningSensibility = 0;
  mainCamera.fov = 0.4;
  mainCamera.layerMask = MASK_3D;
  mainCamera.attachControl(canvas, true);

  const guiCamera = new BABYLON.FreeCamera("guiCam", BABYLON.Vector3.Zero(), scene);
  guiCamera.layerMask = MASK_GUI;
  guiCamera.clearFlags = BABYLON.Camera.LENSCLEARMODE_DEPTH | BABYLON.Camera.LENSCLEARMODE_STENCIL;

  scene.activeCameras = [mainCamera, guiCamera];

  const hemiLight_Before = new BABYLON.HemisphericLight("hemiLight_Before", new BABYLON.Vector3(0, 1, 0), scene);
  hemiLight_Before.intensity = 0.2;

  const hemiLight = new BABYLON.HemisphericLight("hemiLight_After", new BABYLON.Vector3(0, 1, 0), scene);
  hemiLight.intensity = 0.3;

  var dirLight = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(-0.63, -0.7, -0.77), scene);
  dirLight.position = new BABYLON.Vector3(-6.14, 24, 46.37);
  dirLight.diffuse = BABYLON.Color3.FromHexString("#FFF8E3");
  dirLight.intensity = 1.3;

  var pointLight = new BABYLON.PointLight("pointLight", new BABYLON.Vector3(-0.87, 1.64, 0.91), scene);
  pointLight.diffuse = BABYLON.Color3.FromHexString("#EDD9B4");
  pointLight.intensity = 1.5;

  let shadowGenerator_D = new BABYLON.CascadedShadowGenerator(1024, dirLight);
  shadowGenerator_D.autoCalcDepthBounds = true;
  shadowGenerator_D.lambda = 1;
  shadowGenerator_D.bias = 0.002;
  shadowGenerator_D._darkness = -0.1;
  shadowGenerator_D.stabilizeCascades = true;

  // RTT
  const rttSize = { width: engine.getRenderWidth(), height: engine.getRenderHeight() };
  const rttBefore = new BABYLON.RenderTargetTexture("rttBefore", rttSize, scene);
  const rttAfter = new BABYLON.RenderTargetTexture("rttAfter", rttSize, scene);

  rttBefore.activeCamera = mainCamera;
  rttAfter.activeCamera = mainCamera;
  scene.customRenderTargets.push(rttBefore, rttAfter);

  rttBefore.onBeforeRenderObservable.add(() => {
    hemiLight.setEnabled(false);
    dirLight.setEnabled(false);
    pointLight.setEnabled(false);

    hemiLight_Before.setEnabled(true);
  });
  rttAfter.onBeforeRenderObservable.add(() => {
    hemiLight.setEnabled(true);
    dirLight.setEnabled(true);
    pointLight.setEnabled(true);

    hemiLight_Before.setEnabled(false);
  });

  // Import glb model
  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "pink isometric room.glb").then((result) => {
    const metallicMatName = ["Material.018", "Material.019", "Material.022"];

    result.meshes.forEach((mesh) => {
      if (mesh.getTotalVertices() > 0) {
        mesh.layerMask = MASK_3D;
        rttBefore.renderList.push(mesh);
        rttAfter.renderList.push(mesh);

        shadowGenerator_D.addShadowCaster(mesh);
        mesh.receiveShadows = true;
      }

      if (mesh.material) {
        if (mesh.material instanceof BABYLON.PBRMaterial && !metallicMatName.includes(mesh.material.name)) {
          mesh.material.roughness = 0.8;
          mesh.material.metallic = 0;
          mesh.material.directIntensity = 1.0;
          mesh.material.environmentIntensity = 0.5;
        }

        if (mesh.material.name === "Material.021") {
          mesh.material.emissiveColor = BABYLON.Color3.FromHexString("#FFB200");
        }
        if (mesh.material.name === "Material.019" || mesh.material.name === "Material.018") {
          mesh.material.metallic = 0.7;
        }
      }
    });

    dirLight.getShadowGenerator().getShadowMap().resize(1024);
    dirLight.getShadowGenerator().getShadowMap().scale(Math.pow(2, 2));
  });

  // Post Process
  const shaderName = "compareSplitWithEffects";
  BABYLON.Effect.ShadersStore[shaderName + "FragmentShader"] = `
        precision highp float;
        varying vec2 vUV;
        uniform sampler2D uRttBefore;
        uniform sampler2D uRttAfter;
        uniform float uSplitPosition;
        
        uniform float exposure;
        uniform float contrast;
        uniform float saturation;

        vec3 aces_tonemap(vec3 color) {
            float a = 2.51, b = 0.03, c = 2.43, d = 0.59, e = 0.14;
            return clamp((color * (a * color + b)) / (color * (c * color + d) + e), 0.0, 1.0);
        }

        void main(void) {
            if (vUV.x < uSplitPosition) {
                // Before 영역: 원본 RTT 출력
                gl_FragColor = texture2D(uRttBefore, vUV);
            } else {
                // After 영역: RTT에 효과 적용
                vec4 texAfter = texture2D(uRttAfter, vUV);
                vec3 color = texAfter.rgb;

                color *= exposure;
                color = aces_tonemap(color);
                color = mix(vec3(0.5), color, contrast);
                float gray = dot(color, vec3(0.299, 0.587, 0.114));
                color = mix(vec3(gray), color, saturation);

                gl_FragColor = vec4(color, texAfter.a);
            }
        }
    `;

  let currentSplit = 0.5;
  const post = new BABYLON.PostProcess(
    "CompositePP",
    shaderName,
    ["uSplitPosition", "exposure", "contrast", "saturation"],
    ["uRttBefore", "uRttAfter"],
    1.0,
    mainCamera,
  );

  post.onApply = (eff) => {
    eff.setTexture("uRttBefore", rttBefore);
    eff.setTexture("uRttAfter", rttAfter);
    eff.setFloat("uSplitPosition", currentSplit);
    eff.setFloat("exposure", 1.25);
    eff.setFloat("contrast", 1.3);
    eff.setFloat("saturation", 1.6);
  };

  // GUI
  const adt = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI", true, scene);
  adt.layer.layerMask = MASK_GUI;

  const handleGroup = new BABYLON.GUI.Container("handleGroup");
  handleGroup.width = "80px";
  handleGroup.height = "100%";
  handleGroup.isPointerBlocker = true;
  adt.addControl(handleGroup);

  const splitLine = new BABYLON.GUI.Rectangle();
  splitLine.width = "4px";
  splitLine.height = "100%";
  splitLine.color = "black";
  splitLine.background = "white";
  handleGroup.addControl(splitLine);

  const handleCircle = new BABYLON.GUI.Ellipse();
  handleCircle.width = "60px";
  handleCircle.height = "60px";
  handleCircle.background = "white";
  handleCircle.color = "black";
  handleCircle.thickness = 1;
  handleGroup.addControl(handleCircle);

  const handleText = new BABYLON.GUI.TextBlock();
  handleText.text = "< >";
  handleText.color = "black";
  handleText.fontSize = 20;
  handleCircle.addControl(handleText);

  let isDragging = false;

  handleGroup.onPointerDownObservable.add(() => {
    isDragging = true;
    mainCamera.detachControl();
  });

  scene.onPrePointerObservable.add((pointerInfo) => {
    const type = pointerInfo.type;

    if (isDragging && type === BABYLON.PointerEventTypes.POINTERMOVE) {
      const width = engine.getRenderWidth();
      const pointerX = scene.pointerX;

      currentSplit = BABYLON.Scalar.Clamp(pointerX / width, 0, 1);

      const handleWidth = 60;
      const halfHandle = handleWidth / 2;

      const clampedX = BABYLON.Scalar.Clamp(pointerX, halfHandle, width - halfHandle);

      handleGroup.leftInPixels = clampedX - width / 2;
    }

    if (type === BABYLON.PointerEventTypes.POINTERUP) {
      if (isDragging) {
        isDragging = false;
        mainCamera.attachControl(canvas, true);
      }
    }
  });

  handleGroup.leftInPixels = 0;
  const center = engine.getRenderWidth() * 0.5;
  handleGroup.leftInPixels = center - engine.getRenderWidth() / 2;

  const createLabel = (text, alignment) => {
    const label = new BABYLON.GUI.TextBlock();
    label.text = text;
    label.color = "white";
    label.fontSize = 28;
    label.fontWeight = "bold";
    label.fontFamily = "Arial";

    label.width = "200px";
    label.height = "50px";

    label.textHorizontalAlignment = alignment;
    label.textVerticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;

    label.horizontalAlignment = alignment;
    label.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;

    label.shadowBlur = 4;
    label.shadowColor = text === "BEFORE" ? "purple" : "red";
    label.shadowOffsetX = 2;
    label.shadowOffsetY = 2;

    label.top = "40px";

    if (alignment === BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT) {
      label.left = "40px";
    } else {
      label.left = "-40px";
    }

    return label;
  };

  const labelBefore = createLabel("BEFORE", BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT);
  const labelAfter = createLabel("AFTER", BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT);

  adt.addControl(labelBefore);
  adt.addControl(labelAfter);

  // Cascaded Shadow
  let azimuth = -64;
  let elevation = 197;

  const updateLightDirection = (azimuthValue, elevationValue) => {
    if (dirLight) {
      if (elevationValue <= 181) {
        elevationValue = 181;
      } else if (elevationValue >= 359) {
        elevationValue = 359;
      }
      const azimuthRad = BABYLON.Tools.ToRadians(azimuthValue);
      const elevationRad = BABYLON.Tools.ToRadians(elevationValue);

      const x = Math.cos(elevationRad) * Math.sin(azimuthRad);
      const y = Math.sin(elevationRad);
      const z = Math.cos(elevationRad) * Math.cos(azimuthRad);

      dirLight.direction = new BABYLON.Vector3(x, y, z).normalize();
    }
  };

  updateLightDirection(azimuth, elevation);

  // Default Post Process
  const drpp = new BABYLON.DefaultRenderingPipeline("drpp", true, scene, [mainCamera]);
  drpp.fxaaEnabled = true;
  drpp.imageProcessingEnabled = false;
  drpp.bloomEnabled = true;
  drpp.bloomThreshold = 0.7;
  drpp.bloomWeight = 0.6;
  drpp.samples = 4;

  return scene;
}
